void dei_sc_set_mode( Dei_Sc_Mode mode )
{           
    if( dei_sc_mode == DEI_SC_MODE_PROGRAMMING )
    {        
        if( mode == DEI_SC_MODE_NORMAL )
        {                       
            wake_leave_flagged(WAKE_SC_SET_MODE);             
        }
    }
    else
    {
        if( mode == DEI_SC_MODE_PROGRAMMING )
        {
            wake_enter_flagged(WAKE_SC_SET_MODE);             
        }        
    }

    dei_sc_tx_flush() ; 
                
    ATOMIC( dei_sc_mode = mode  ) ;                        

    dei_rf_mode( (Dei_Rf_Mode)mode ) ;
}

